 if(ok<2)c[2].t.push('Cada parágrafo de desenvolvimento precisa de ao menos ~45 palavras, com argumento, justificativa e consequência.');if(ca<3)c[2].t.push('Poucas relações de causa e justificativa (pois, uma vez que, dado que).');if(ex<1)c[2].t.push('Falta exemplificação concreta nos argumentos.');if(iw<30)c[2].t.push('Introdução curta: contextualize e apresente a tese com clareza.');if(!ret)c[2].t.push('A conclusão não retoma a tese e o tema.');
