const C=Array.from({length:innerWidth<600?4:7},(_,k)=>{const c={x:Math.random()*W,y:Math.random()*H,a:Math.random()*6.28,n:14+k*3,sz:4+Math.random()*5,sp:.35+Math.random()*.5,ph:Math.random()*9,s:[]};for(let i=0;i<c.n;i++)c.s.push({x:c.x,y:c.y});return c});
